FLAT=[x for xs in NAV.values() for x in xs]
def badge(kind,text): return f'<span class="badge {kind}">{text}</span>'
def section(i,title,body): return f'<section id="{i}"><h2>{title}</h2>{body}</section>'
def cards(items): return '<div class="cards">'+''.join(f'<article class="card"><h3>{a}</h3><p>{b}</p></article>' for a,b in items)+'</div>'
def table(headers,rows): return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def code(s): return f'<pre><button class="copy" type="button">Copy</button><code>{escape(s)}</code></pre>'
def callout(title,text,kind=''): return f'<aside class="callout {kind}"><strong>{title}</strong><p>{text}</p></aside>'
def flow(nodes): return '<div class="product-map">'+''.join(f'<div class="map-node">{x}</div>'+('<span>→</span>' if i<len(nodes)-1 else '') for i,x in enumerate(nodes))+'</div>'
P={}
def add(slug,title,group,lead,body,toc): P[slug]=(title,group,lead,body,toc)
add('', 'Protect the conditions behind your position.','Getting started','Kelvara continuously verifies the controls behind your DeFi positions and helps you respond while there is still time to act.',
 cards([('Position-specific','Know exactly which capital a change affects.'),('Evidence-backed','Security conclusions are backed by current onchain evidence.'),('Self-custodial','Your wallet remains the authority.')])+section('map','How Kelvara fits together',flow(['Position','Governance','Safeguards','Incident','Protection / ExitRail'])+'<p>Start with the capital. Trace what controls it, verify expected conditions, understand change, then use an owner-authorized response.</p>')+section('start','Start with a position','<p>Kelvara connects each supported position to its control plane, expected safeguards, current evidence, severity, and available response. Findings stay scoped to the affected position.</p>'+badge('live','Live Mainnet workspace')+badge('beta','Coverage constrained')),[('map','How Kelvara fits together'),('start','Start with a position')])
add('how-it-works','How Kelvara works','Getting started','From position discovery to evidence-backed response.',section('model','The position model',cards([('Position','The exact vault and wallet exposure.'),('Control','Programs, authorities, governance, and access paths.'),('Expectation','Versioned conditions Kelvara should verify.'),('Observation','Current evidence, provenance, and freshness.'),('Assessment','Change, severity, and affected capital.'),('Response','Owner-approved action where supported.')]))+section('boundary','Information before action',callout('Read-only first.','Discovery, governance, safeguards, history, and evidence do not grant signing authority. Signing begins only in an explicit protection flow.')),[('model','The position model'),('boundary','Information before action')])
