add('reference/kamino','Kamino integration','Reference','Current kVault discovery and position-specific capability boundaries.',section('coverage','Coverage',table(['Integration','Capability','Status'],[['Institutional Commodity Yield · USDC','Discovery','Live registry'],['Institutional Commodity Yield · USDC','Monitoring','Provisioning'],['Steakhouse USDG High Yield','Discovery','Live registry'],['Steakhouse USDG High Yield','Protection','Beta Mainnet']]))+section('technical','Technical detail','<details><summary>Program and authority evidence</summary><p>Where configured, evidence can resolve the program account, upgradeable-loader state, ProgramData identity, and upgrade authority. These support the position; they are not the product root.</p></details>'),[('coverage','Coverage'),('technical','Technical detail')])
add('reference/squads-v4','Squads V4','Reference','The current governance adapter behind mapped Control Map data.',section('mapping','Mapped data','<ul><li>Provider and generation</li><li>Multisig and vault identity</li><li>Members, permissions, and threshold</li><li>Current actions and finalized activity</li><li>Instruction provenance and freshness</li></ul>'+badge('live','Adapter')+badge('beta','Authenticated Mainnet UI'))+section('unknowns','Unknown instructions','<p>Unsupported or partially decoded instructions retain raw provenance and unresolved status. Kelvara does not infer intent from missing decode evidence.</p>'),[('mapping','Mapped data'),('unknowns','Unknown instructions')])
