CSS='''
:root{color-scheme:light;--bg:#f7f8f5;--paper:#fff;--soft:#f0f3ee;--ink:#111713;--muted:#667169;--line:#dce3dc;--deep:#183c2b;--lime:#b8ef3b;--green:#34744d;--amber:#9a650d;--blue:#315fba;--mono:ui-monospace,SFMono-Regular,Menlo,monospace}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.7 ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;-webkit-font-smoothing:antialiased}a{color:var(--deep);text-underline-offset:3px}.top{position:sticky;top:0;z-index:30;height:68px;border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--bg) 92%,transparent);backdrop-filter:blur(14px)}.top-in{max-width:1500px;height:100%;margin:auto;padding:0 28px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink);font-weight:800}.brand img{width:31px;height:31px}.brand small{color:var(--muted);font-weight:500}.top nav{display:flex;gap:22px;align-items:center}.top nav a{text-decoration:none;color:var(--muted);font-size:13px}.launch{padding:9px 14px;border-radius:8px;background:var(--deep);color:#fff!important;font-weight:750}.menu{display:none;border:1px solid var(--line);background:var(--paper);color:var(--ink);padding:8px 12px;border-radius:8px}.shell{max-width:1500px;margin:auto;display:grid;grid-template-columns:240px minmax(0,800px) 190px;gap:58px;padding:48px 28px 100px}.side,.toc{position:sticky;top:96px;max-height:calc(100vh - 120px);overflow:auto}.nav-group{margin-bottom:25px}.nav-group>b,.toc>b{display:block;margin-bottom:8px;color:#8a958d;font:700 10px var(--mono);letter-spacing:.1em;text-transform:uppercase}.nav-group a,.toc a{display:block;padding:5px 9px;margin-left:-9px;border-radius:6px;color:var(--muted);text-decoration:none;font-size:12px}.nav-group a:hover,.nav-group a.active{color:var(--ink);background:var(--soft)}.article{min-width:0}.crumb{color:var(--muted);font-size:12px;margin-bottom:34px}.eyebrow{font:750 10px var(--mono);letter-spacing:.12em;text-transform:uppercase;color:var(--green)}h1{font-size:clamp(42px,6vw,72px);line-height:.98;letter-spacing:-.055em;margin:12px 0 22px;max-width:780px}h2{font-size:31px;line-height:1.12;letter-spacing:-.035em;margin:0 0 18px}h3{font-size:17px;margin:0 0 8px}.lead{font-size:20px;line-height:1.55;color:#425047;max-width:720px;margin-bottom:36px}.article p,.article li{color:#4f5d54}.article section{padding:54px 0;border-top:1px solid var(--line)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:28px 0}.card{border:1px solid var(--line);background:var(--paper);border-radius:12px;padding:20px}.card p{font-size:13px;margin:0}.product-map{display:flex;align-items:center;gap:10px;margin:28px 0;padding:28px;background:var(--deep);border-radius:15px;color:#fff}.product-map>span{color:var(--lime)}.map-node{flex:1;padding:13px 8px;border:1px solid #ffffff30;border-radius:8px;text-align:center;font-weight:750}.badge{display:inline-flex;border:1px solid var(--line);border-radius:999px;padding:4px 8px;margin:0 5px 5px 0;font:750 10px var(--mono);letter-spacing:.04em;text-transform:uppercase}.live{color:var(--green);background:#eef9f1}.beta{color:var(--amber);background:#fff8e5}.dev{color:var(--blue);background:#edf3ff}.planned{color:var(--muted);background:var(--soft)}.callout{margin:24px 0;padding:18px 20px;border:1px solid var(--line);border-radius:10px;background:var(--soft)}.callout strong{display:block;margin-bottom:4px}.callout p{margin:0}.callout.warn{background:#fff8e7;border-color:#ead9a8}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px;margin:24px 0}table{border-collapse:collapse;width:100%;min-width:620px;background:var(--paper)}th,td{text-align:left;vertical-align:top;padding:13px 15px;border-bottom:1px solid var(--line)}th{font:750 10px var(--mono);letter-spacing:.05em;text-transform:uppercase;color:var(--muted)}td{font-size:13px;color:#4f5d54}tr:last-child td{border-bottom:0}pre{position:relative;overflow:auto;background:#101712;color:#dce9df;border-radius:10px;padding:20px;font:12px/1.7 var(--mono)}code{font-family:var(--mono)}.copy{position:absolute;right:10px;top:10px;border:1px solid #ffffff28;border-radius:5px;background:#ffffff0c;color:#c8d3ca;padding:5px 8px}.next{display:flex;justify-content:space-between;gap:15px;margin-top:58px;padding-top:24px;border-top:1px solid var(--line)}.next a{min-width:180px;text-decoration:none;border:1px solid var(--line);background:var(--paper);border-radius:10px;padding:14px 17px}.next small{display:block;color:var(--muted)}.toc a{padding:4px 0}.updated{margin-top:50px;color:var(--muted);font-size:11px}details{border-top:1px solid var(--line);padding:15px 0}summary{cursor:pointer;font-weight:700}@media(max-width:1100px){.shell{grid-template-columns:220px minmax(0,1fr)}.toc{display:none}}@media(max-width:760px){.top-in{padding:0 16px}.top nav>a:not(.launch){display:none}.menu{display:block}.shell{display:block;padding:28px 18px 72px}.side{display:none}.side.open{display:block;position:fixed;inset:68px 0 0;z-index:35;max-height:none;background:var(--bg);padding:24px;overflow:auto}.cards{grid-template-columns:1fr}.product-map{flex-direction:column}.product-map>span{transform:rotate(90deg)}.map-node{width:100%}.article section{padding:42px 0}h1{font-size:44px}.lead{font-size:17px}.next{flex-direction:column}.next a{width:100%}}@media(prefers-color-scheme:dark){:root{color-scheme:dark;--bg:#0d120f;--paper:#151c17;--soft:#1b241d;--ink:#edf3ee;--muted:#9ca9a0;--line:#2d3931;--deep:#9cdaa9;--green:#82c995;--amber:#e3b964;--blue:#91b4ff}.top{background:#0d120fea}.launch{background:#e8f0e9;color:#101612!important}.lead,.article p,.article li,td{color:#b8c3ba}.product-map{background:#17231b}.live{background:#17301e}.beta,.callout.warn{background:#372d18}.dev{background:#1b2941}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
'''
JS="""const m=document.querySelector('.menu'),s=document.querySelector('.side');m?.addEventListener('click',()=>{const o=s.classList.toggle('open');m.setAttribute('aria-expanded',String(o))});s?.querySelectorAll('a').forEach(a=>a.onclick=()=>s.classList.remove('open'));document.querySelectorAll('.copy').forEach(b=>b.onclick=async()=>{await navigator.clipboard.writeText(b.parentElement.querySelector('code').innerText);b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1200)});"""
def render(slug,title,group,lead,body,toc):
 nav=''.join('<div class="nav-group"><b>'+g+'</b>'+''.join(f'<a class="{"active" if x==slug else ""}" href="/docs/{x+"/" if x else ""}">{n}</a>' for n,x in xs)+'</div>' for g,xs in NAV.items())
 i=[x for _,x in FLAT].index(slug); prev=FLAT[i-1] if i else None; nxt=FLAT[i+1] if i+1<len(FLAT) else None
 pager='<nav class="next">'+(f'<a href="/docs/{prev[1]+"/" if prev[1] else ""}"><small>Previous</small>← {prev[0]}</a>' if prev else '<span></span>')+(f'<a href="/docs/{nxt[1]+"/" if nxt[1] else ""}"><small>Next</small>{nxt[0]} →</a>' if nxt else '')+'</nav>'
 right='<aside class="toc"><b>On this page</b>'+''.join(f'<a href="#{x}">{t}</a>' for x,t in toc)+'</aside>'
 url='https://kelvara.xyz/docs/'+(slug+'/' if slug else '')
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Kelvara Docs</title><meta name="description" content="{escape(lead,quote=True)}"><link rel="canonical" href="{url}"><link rel="icon" href="/assets/kelvara-icon.png"><link rel="stylesheet" href="/docs/docs.css"></head><body><header class="top"><div class="top-in"><a class="brand" href="/"><img src="/assets/kelvara-icon.png" alt="">Kelvara <small>Docs</small></a><nav><a href="/">Product</a><a href="/docs/">Docs</a><button class="menu" aria-expanded="false">Menu</button><a class="launch" href="https://app.kelvara.xyz/">Open app ↗</a></nav></div></header><div class="shell"><aside class="side">{nav}</aside><main class="article"><div class="crumb">Kelvara Docs / {group}</div><p class="eyebrow">{group}</p><h1>{title}</h1><p class="lead">{lead}</p>{body}{pager}<p class="updated">Verified against current application contracts · 11 October 2026</p></main>{right}</div><script src="/docs/docs.js"></script></body></html>'''
 path=R/(slug or '.')/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(html)
R.mkdir(exist_ok=True);(R/'docs.css').write_text(CSS);(R/'docs.js').write_text(JS)
for slug,args in P.items(): render(slug,*args)
print(f'wrote {len(P)} pages')
